def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    stack = []
    current_group = ""

    for char in paren_string:
        if char == '(':
            if current_group:
                stack.append(current_group)
            current_group = "("
        elif char == ')':
            current_group += ")"
            if stack:
                current_group = stack.pop() + current_group
            result.append(current_group)
            current_group = ""

    return result

